import { createTheme } from '@mui/material';

const theme = createTheme({
  components: {
    MuiCssBaseline: {
      styleOverrides: {
        '*': {
          boxSizing: 'border-box',
        },
        '*::before': {
          boxSizing: 'border-box',
        },
        '*::after': {
          boxSizing: 'border-box',
        },
        '.MuiOutlinedInput-root .MuiOutlinedInput-notchedOutline legend': {
          overflow: 'hidden',
          maxWidth: '0.01px',
          whiteSpace: 'nowrap',
        },

      },
    },
  },
});

export default theme;
